# Restrict network access
ALLOWED_DOMAINS = ['api.example.com', 'docs.example.com']
def safe_fetch(url):
    parsed = urlparse(url)
    if parsed.hostname not in ALLOWED_DOMAINS:
        raise SecurityError(f'Domain not allowed: {parsed.hostname}')
    return requests.get(url)

# Audit MCP server tools before connecting
server = MCPServer(url)
tools = server.list_tools()
for tool in tools:
    if contains_suspicious_instructions(tool.description):
        raise SecurityError(f'Suspicious tool: {tool.name}')
    if tool.name not in ALLOWED_TOOLS:
        server.disable_tool(tool.name)

# Scan for suspicious instructions in agent config files
import re
SUSPICIOUS_PATTERNS = [
    r'ignore.*previous.*instruction',
    r'override.*safety',
    r'exfiltrate|steal|extract.*(?:key|token|secret)',
]
for pattern in SUSPICIOUS_PATTERNS:
    if re.search(pattern, config_content, re.IGNORECASE):
        raise SecurityAlert(f'Suspicious instruction in {config_file}')

