// Safe hook with 'if' conditional guard (v2.1.85+)
// The 'if' field uses permission rule syntax to filter when hooks spawn
{
  "hooks": {
    "PreToolUse": [{
      "if": "Bash(git *)",
      "matcher": "Bash(git *)",
      "hooks": [{
        "type": "command",
        "command": "echo 'git command detected'"
      }]
    }]
  }
}
// Without 'if', the hook process spawns for EVERY tool call — 'if' reduces overhead

// In settings.json — block shell execution in skills
{
  "disableSkillShellExecution": true
}

// If a skill MUST use shell, document the commands explicitly
// and use an allowlist in managed-settings.json

// In settings.json
{
  "sandbox": {
    "enabled": true,
    "failIfUnavailable": true
  }
}

// In managed-settings.json
{
  "allowedChannelPlugins": [
    "@company/approved-plugin-1",
    "@company/approved-plugin-2"
  ]
}

// Or per-team in managed-settings.d/security-team.json
{
  "allowedChannelPlugins": ["sentinel", "@company/security-tools"]
}

// Good: concise MCP tool description
