// managed-settings.json (enterprise deployment)
{
  "forceRemoteSettingsRefresh": true,
  "sandbox": { "failIfUnavailable": true },
  "disableSkillShellExecution": true,
  "allowedChannelPlugins": ["sentinel"]
}

// settings.json — defense-in-depth
{
  "permissions": {
    "deny": ["Bash(rm -rf *)", "Bash(curl * | bash)"]
  },
  "hooks": {
    "PreToolUse": [{
      "if": "Bash",
      "hooks": [{ "type": "command", "command": "echo '{\"permissionDecision\": \"ask\"}'"}]
    }]
  }
}

